import os
import json

# Look for tokenizer files
for root, dirs, files in os.walk('/work'):
    for f in files:
        if any(x in f.lower() for x in ['tokenizer', 'vocab', 'config', 'special']):
            print(f"Found: {os.path.join(root, f)}")

# Check if there's a model config
for root, dirs, files in os.walk('/work'):
    for f in files:
        if f.endswith('.json'):
            path = os.path.join(root, f)
            try:
                with open(path) as fp:
                    data = json.load(fp)
                print(f"\n{path}:")
                print(json.dumps(data, indent=2)[:2000])
            except:
                pass
